   577  int
   578  cdf_read_long_sector_chain(const cdf_info_t *info, const cdf_header_t *h,
   579      const cdf_sat_t *sat, cdf_secid_t sid, size_t len, cdf_stream_t *scn)
   580  {
   581          size_t ss = CDF_SEC_SIZE(h), i, j;
   582          ssize_t nr;
   583          scn->sst_tab = NULL;
   584          scn->sst_len = cdf_count_chain(sat, sid, ss);
   585          scn->sst_dirlen = MAX(h->h_min_size_standard_stream, len);
   586          scn->sst_ss = ss;
   587
   588          if (sid == CDF_SECID_END_OF_CHAIN || len == 0)
   589                  return cdf_zero_stream(scn);
   590
   591          if (scn->sst_len == CAST(size_t, -1))
   592                  goto out;
   593
   594          scn->sst_tab = CDF_CALLOC(scn->sst_len, ss);
   595          if (scn->sst_tab == NULL)
   596                  return cdf_zero_stream(scn);
   597
   598          for (j = i = 0; sid >= 0; i++, j++) {
   599                  if (j >= CDF_LOOP_LIMIT) {
   600                          DPRINTF(("Read long sector chain loop limit"));
   601                          goto out;
   602                  }
   603                  if (i >= scn->sst_len) {
   604                          DPRINTF(("Out of bounds reading long sector chain "
   605                              "%" SIZE_T_FORMAT "u > %" SIZE_T_FORMAT "u\n", i,
   606                              scn->sst_len));
   607                          goto out;
   608                  }
   609                  if ((nr = cdf_read_sector(info, scn->sst_tab, i * ss, ss, h,
   610                      sid)) != CAST(ssize_t, ss)) {
   611                          if (i == scn->sst_len - 1 && nr > 0) {
   612                                  /* Last sector might be truncated */
   613                                  return 0;
   614                          }
   615                          DPRINTF(("Reading long sector chain %d", sid));
   616                          goto out;
   617                  }
   618                  sid = CDF_TOLE4(CAST(uint32_t, sat->sat_tab[sid]));
   619          }
   620          return 0;
   621  out:
   622          errno = EFTYPE;
   623          return cdf_zero_stream(scn);
   624  }
